Let $\mathbf{L}$ be an $n \times n$ quasi-Laplacian matrix and ${{\boldsymbol{\Sigma}}}={\mathbf{L}}^-$. Let ${{\boldsymbol{\Sigma}}} =: \mathbf{W} {\boldsymbol{\Lambda}} \mathbf{W}^\top$ be the eigendecomposition of ${{\boldsymbol{\Sigma}}}$, with ${\boldsymbol{\Lambda}} = \mathrm{diag}\left( 
            \begin{bmatrix}
                \lambda_1,\dots,\lambda_n
            \end{bmatrix}
         \right)$ and $\lambda_1\geq\dots\geq\lambda_{n-1}>\lambda_n=0$. Let $\mathbf{Q}$ be defined as in Subsection 3.1. Then, the eigenvalues $\lambda_n(\mathbf{Q})<\lambda_1(\mathbf{Q})\leq \dots \leq \lambda_{n-1}(\mathbf{Q})$ of $\mathbf{Q}$ are:
        \begin{equation*}
            \lambda_i(\mathbf{Q}) = \begin{dcases}
                 \frac{1}{2} \left( \lambda_i^{-1}+\sqrt{\lambda_i^{-2}-2\alpha(p-2)\lambda_i^{-1}+\alpha^2 p^2}+\alpha(p-2) \right)\qquad &i\ne n\\
                \alpha(p-1)\qquad &\text{$i=n$}.
            \end{dcases}
        \end{equation*}
        In particular the smallest eigenvalue of $\mathbf{Q}$, $\lambda_n(\mathbf{Q})$, is strictly positive, thus $\mathbf{Q}$ is strictly positive definite. In addition, $\mathbf{Q} {\mathbf{1}_{n}}=\alpha(p-1){\mathbf{1}_{n}}$.

Let $\mathbf{L}$ be an $n \times n$ quasi-Laplacian matrix,  

        ${{\boldsymbol{\Sigma}}}={\mathbf{L}}^-$ and $\alpha >0$. Furthermore, let $\mathbf{Q}$ and $\mathbf{X}$ as defined in Subsection 3.1. Then the following holds:
        \begin{enumerate}
            \item ${{\boldsymbol{\Sigma}}}$, $\mathbf{L}$, $\mathbf{Q}$ and $\mathbf{X}$ commute;
            \item ${{\boldsymbol{\Sigma}}} {\mathbf{L}}= {\mathbf{L}}{{\boldsymbol{\Sigma}}} = \mathbf{I}_n-\frac{1}{n} {\mathbf{1}_{n\times n}}$;
            \item  $\mathbf{Q}^2-\alpha^2 (p-1) \mathbf{I}_n - \mathbf{Q} {\mathbf{L}}- \alpha (p-2) \mathbf{Q} + \alpha (p-2) {\mathbf{L}}= \mathbf{0}$;
            \item  ${{\boldsymbol{\Sigma}}} \mathbf{Q}^2 - \alpha^2 (p-1) {{\boldsymbol{\Sigma}}} - \mathbf{Q} - \alpha (p-2) {{\boldsymbol{\Sigma}}} \mathbf{Q} + \alpha (p-2) \mathbf{I}_n + \frac{\alpha}{n} {\mathbf{1}_{n\times n}}=\mathbf{0}$.
        \end{enumerate}

Let ${\mathbf{K}}_{{\bm{Z}}_V}$, ${\mathbf{K}}_{{\bm{Z}}_E}$ be the covariance mappings associated respectively with the {random fields} ${\bm{Z}}_V$ and ${\bm{Z}}_E$. Then, it is true that 
        \begin{equation}
            {\mathbf{K}}_{{\bm{Z}}_V}(u_1,u_2)=\mathcal{M}_{p}\begin{pmatrix} {\bm{\delta}}_{{1,V}}^\top \Tilde {{\boldsymbol{\Sigma}}}{\bm{\delta}}_{{2,V}}\\ {\bm{\delta}}_{{1,V}}^\top \Tilde {\mathbf{X}}{\bm{\delta}}_{{2,V}} \end{pmatrix} \in \mathbb{R}^{p\times p},
        \end{equation}
        for $u_i=(\underline{u}_i, \overline{u}_i, \delta_i)\in \mathcal G$ ($i\in\left\{ 1,2 \right\}$), and where ${\bm{\delta}}_{{i,V}}$ is the $n$-dimensional vector whose entries are 
        \begin{equation}

            {\delta}_{{i,{V}}}:=\begin{cases}
                1-\delta_i \quad &\text{if }v=\underline{u}_i\\
                \delta_i \quad &\text{if }v=\overline{u}_i\\
                0 \quad &\text{otherwise}  
            \end{cases}, \quad  v\in V.
        \end{equation}
        Further, it is true that 
        \begin{equation*}
            {\mathbf{K}}_{{\bm{Z}}_E}(u_1,u_2)=\mathcal{M}_{p}\begin{pmatrix} \mathbbm{1}\left( e_1=e_2 \right)\ell(e_1)\left( \delta_1 \wedge \delta_2 - \delta_1 \delta_2 \right)\\ \beta \mathbbm{1}\left( e_1=e_2 \right)\ell(e_1)\left( \delta_1 \wedge \delta_2 - \delta_1 \delta_2 \right) \end{pmatrix}.
        \end{equation*}

Let $\psi: [0,+\infty)\to {(0,+\infty)}$ be a {non-constant} completely monotone function, $g:[0,+\infty)\to {[0,+\infty)}$ {be} a Bernstein function and let ${\boldsymbol{\Gamma}}_{{{\bm{Z}}}}: X\times X\to [0,+\infty)^{p\times p}$, for a non-empty set $X$. If, for all ${x_1,x_2}\in X$, ${\boldsymbol{\Gamma}}_{{{\bm{Z}}}}^\top(x_1,x_2)={\boldsymbol{\Gamma}}_{{{\bm{Z}}}}(x_2,x_1)$ and ${\boldsymbol{\Gamma}}_{{{\bm{Z}}}}$ is ${\mathbf{1}_{p}}$-conditionally negative semidefinite, then, for all ${\xi}>0$,
        \begin{equation*}
            ({x_1,x_2})\mapsto \psi\Big ({\xi} \, g\left( {\boldsymbol{\Gamma}}_{{{\bm{Z}}}}({x_1,x_2} \right)\Big ), \qquad {x_1,x_2}\in X,
        \end{equation*}
        where $\psi$ and $g$ are applied element-wise, is a positive semidefinite function on $X$.

Let ${\cal G}$ be a graph with Euclidean edges and $\mathbf{D}: \mathcal G\times \mathcal G \to {[0,+\infty)}^{p\times p}$ the distance defined at (28). In addition, let $\psi:[0,+\infty)\to (0,+\infty)$ be a non-constant completely monotone function and $g: [0,+\infty)\to [0,+\infty)$ a Bernstein function. Then, for every $ {\xi}>0$, the mapping  {$\mathbf{K}$ defined as}
        \begin{equation}

            (u_1,u_2)\mapsto  {\mathbf{K}(u_1,u_2)} = \psi\left(  {\xi}\,g\left( \mathbf{D}(u_1,u_2) \right) \right),
        \end{equation}
        where $\psi$ and $g$ are applied element-wise, is a valid covariance function. If, in addition, $\psi(0)=1$, then (30) is a valid correlation function.

Let $\mathbf{L}$ be a quasi-Laplacian matrix partitioned as follows: 
        \begin{equation}

            {\mathbf{L}}=\begin{bmatrix}
                {\mathbf{A}} & {\mathbf{B}}\\
                {\mathbf{B}}^\top & {\mathbf{C}}
            \end{bmatrix},
        \end{equation}
        where ${\mathbf{A}}$ and ${\mathbf{C}}$ are square matrices. Then the following statements hold.
        \begin{enumerate}
            \item ${\mathbf{B}}\ne {\boldsymbol{0}}$.
            \item ${\mathbf{A}}$ and ${\mathbf{C}}$ are strictly positive definite.
            \item Both ${\mathbf{L}}/{\mathbf{C}}:={\mathbf{A}}-{\mathbf{B}} {\mathbf{C}}^{-1} {\mathbf{B}}^\top$ and ${\mathbf{L}}/{\mathbf{A}}:={\mathbf{C}} - {\mathbf{B}}^\top {\mathbf{A}}^{-1} {\mathbf{B}}$ are quasi-Laplacian matrices, \textit{i.e. }, the set of quasi-Laplacian matrices is closed under the Schur complement operation.
            \item ${\mathbf{L}}^-$ is a quasi-Laplacian matrix.
        \end{enumerate}

Let $\mathbf{L}$ an $n\times n$ Laplacian matrix, let ${{\boldsymbol{\Sigma}}}:={\mathbf{L}}^-$ its Moore-Penrose inverse and let $\alpha > 0$. Let ${\boldsymbol{\Theta}}$, $\mathbf{Q}$, $\mathbf{X}$, $k_1$, $k_2$, $\Tilde{{{\boldsymbol{\Sigma}}}}$ and $\Tilde{\mathbf{X}}$ as described in Subsection 3.1. Finally let:
    	\begin{equation}

    		\Tilde {\mathbf{K}} := \mathcal{M}_{p}\begin{pmatrix} \Tilde {{\boldsymbol{\Sigma}}}\\ \Tilde {\mathbf{X}} \end{pmatrix}.
    	\end{equation}
    	Then $\Tilde{\mathbf{K}}={\boldsymbol{\Theta}}^-$.

Let ${\cal G}$ be a graph with Euclidean edges and let $\mathbf{D}: \mathcal G\times \mathcal G \to {[0,+\infty)}^{p\times p}$ as defined in (28) and having elements $D_{ij}$, $i,j=1,\ldots, p$. Then, the following properties hold: 
        \begin{enumerate}
            \item for all $i\in\left\{ 1,\dots,p \right\}$, the distance $D_{ii}$ coincides with the resistance distance defined by [anderes_isotropic_2020], \textit{i.e. } $D_{ii}(u_1,u_2)=d_{R}(u_1,u_2)$;
            \item the distance $\mathbf{D}$ is matrix-homogeneous, \textit{i.e. } for every $ i\ne j$ and $\,i'\ne j'$, we have $D_{ij}(u_1,u_2)=D_{i'j'}(u_1,u_2)$ and $D_{ii}(u_1,u_2)=D_{i'i'}(u_1,u_2)$.  
        \end{enumerate}

Let $\mathbf{K} : X \times X \to \mathbb{R}^{p\times p}$. Then, {the following} are equivalent:
        \begin{itemize}
            \item $\mathbf{K}$ is positive semidefinite;
            \item for all $n\in\left\{ 1,2,\dots \right\}$ and for all ${x}_1,\dots, {x}_n\in X$, the $np \times np$ block matrix $\mathbf{C}:=[C_{ij}]_{i,j=1}^{np}:=[\mathbf{K}({x}_i,{x}_j)]_{i,j=1}^{{n}}$ is positive semidefinite, \textit{i.e. }, ${\bm{c}}^\top \mathbf{C} {\bm{c}} \geq 0$ for any ${\bm{c}} \in \mathbb{R}^{np}$. 
        \end{itemize}

The matrix-valued expression (28) satisfies properties similar to the (real-valued) quasi-metrics, \textit{i.e. } it satisfies:
        \begin{enumerate}
            \item $D_{ij}(u_1,u_2)\geq 0$;
            \item $D_{ij}(u_1,u_2)=0 \iff u_1=u_2$ and $i=j$;
            \item $\mathbf{D}(u_1,u_2) = \mathbf{D}(u_1,u_2)^\top = \mathbf{D}(u_2,u_1) = \mathbf{D}(u_2,u_1)^\top$ for any $u_1, u_2 \in \mathcal G$;
            \item The mapping $(u_1,u_2) \mapsto \mathbf{D}(u_1,u_0) \mathbf{A} + \mathbf{A}^\top \mathbf{D}(u_0,u_2) - \mathbf{D}(u_1,u_2) - \mathbf{A}^\top \mathbf{D}(u_0,u_0) \mathbf{A}$ is positive semidefinite for any $u_0 \in \mathcal G$ and any $p\times p$ matrix $\mathbf{A}$ such that $\mathbf{A}^\top {\mathbf{1}_{p}} = {\mathbf{1}_{p}}$;
            \item {The matrices $\mathbf{D}(u_1,u_2)-\mathbf{D}(u_0,u_0)$ and  $2\mathbf{D}(u_1,u_0)+2\mathbf{D}(u_2,u_0)-\mathbf{D}(u_1,u_2)-3\mathbf{D}(u_0,u_0)$ are symmetric and positive semidefinite for any $u_0,u_1,u_2 \in \mathcal G$.}
        \end{enumerate}

Let $m,p$ be two positive integers. {Let $m^\prime:=\lceil m/2 \rceil$.} Let ${\mathbf{K}}: [0,+\infty) \to \mathbb{R}^{p \times p}$ be continuous with ${\mathbf{K}}(0)= \mathbf{1}_{p \times p}$. Then, ${\mathbf{K}}$ belongs to the class $\Phi_m^p$ if and only if 
    \begin{equation}
         {\mathbf{K}}(t) = \int_0^{+\infty} \omega_{{m^\prime}} (rt ) \,{\mathbf{F}}({\rm d}r), \qquad t \ge 0,
    \end{equation}
    where ${\mathbf{F}}$ is a {bounded} {symmetric} matrix-valued measure such that ${\mathbf{F}} ({\rm d}r)$ is positive {semi}definite for all $r >0$, and where 
    \begin{equation}

        \omega_{{m^\prime}}(t) = \frac{\Gamma({m^\prime}/2)}{\sqrt{\pi} \Gamma(({m^\prime}-1)/2)} \int_{1}^{+\infty} \Omega_{{m^\prime}} (\sqrt{v}t) v^{-{m^\prime}/2} (v-1)^{({m^\prime}-3)/2} {\rm d} v,  
    \end{equation}
   with $\Omega_{{m^\prime}}$ being the characteristic function of a random vector that is uniformly distributed over the {unit sphere} $\mathbb{S}^{{m^\prime}-1}$ embedded in $\mathbb{R}^{{m^\prime}}$.

Let $m,p$ be positive integers. {Let $m^\prime:=\lceil m/2 \rceil$.} Let $\mathbf{H}$ be a member of the class $\Psi_{2{m^\prime}-1}^p$. Let the mapping ${\mathbf{K}}$ be defined through
    \begin{equation}

        {\mathbf{K}}(t) = I^{({m^\prime}-1)} \mathbf{H}(t), \qquad t \ge 0,
    \end{equation}
    where $I^{({m^\prime}-1)}$ is the $({m^\prime}-1)$ iterated application of the operator $I$, defined as 
    \begin{equation*}  
        (If)(t) := \frac{\int_{t}^{+\infty} f(u) {\rm d} u}{\int_{0}^{+\infty} f(u) {\rm d} u}.
    \end{equation*}
    Then, ${\mathbf{K}}$ belongs to the class $\Phi_m^p$.

Let $m,p$ be positive integers. Let $m^\prime:=\lceil m/2 \rceil$. Let $[\rho_{ij}]_{i,j=1}^p$, $[b_{ij}]_{i,j=1}^p$ and $[\nu_{ij}]_{i,j=1}^p$ be real symmetric matrices such that $b_{ij}>0$ and $\nu_{ij}>2{m^\prime}-1$ for $i,j=1,\ldots,p$. 
    For $r > 0$, define $\mathbf{A}(r)$ with entries
    \begin{equation}

        A_{ij}(r) = \frac{\rho_{ij} \Gamma({\frac{\nu_{ij}}{2}})}{\Gamma({\frac{\nu_{ij}}{2}}-{m^\prime}+\frac{1}{2}) \Gamma({{m^\prime}-\frac{1}{2}})} \left ( 1- b_{ij}^2 r^2 \right )_+^{{\frac{\nu_{ij}}{2}}-{{m^\prime}-\frac{1}{2}}}, \quad i,j=1,\ldots,p.
    \end{equation}
    Then, the mapping $\mathbf{K}: [0,+\infty) \to \mathbb{R}^{p \times p} $ with entries 
    \begin{equation}

        K_{ij}(x) = \frac{\rho_{ij}}{b_{ij}^{{2{m^\prime}-1}}} \, \omega_{\nu_{ij}} \left ( \frac{x}{b_{ij}}\right ), \qquad x\ge 0, \quad i,j=1,\ldots, p,
    \end{equation}
    belongs to $\Phi_m^p$ provided the matrix $\mathbf{A}(r)$ as defined in (42) is positive semidefinite for any $r > 0$.

