It is true that
        \begin{align}

            &{\mathbf{K}}_{{\bm{Z}}}(u_1,u_2)={\mathbf{K}}_{{\bm{Z}}_V}(u_1,u_2)+{\mathbf{K}}_{{\bm{Z}}_E}(u_1,u_2)\\
            &=\mathcal{M}_{p}\begin{pmatrix} \boldsymbol{\delta}_{{1,V}}^\top \Tilde {{\boldsymbol{\Sigma}}}{\bm{\delta}}_{{2,V}} + \mathbbm{1}\left( e_1=e_2 \right)\ell(e_1)\left( \delta_1 \wedge \delta_2 - \delta_1 \delta_2 \right)\\ {\bm{\delta}}_{{1,V}}^\top \Tilde {\mathbf{X}}{\bm{\delta}}_{{2,V}} + \beta \mathbbm{1}\left( e_1=e_2 \right)\ell(e_1)\left( \delta_1 \wedge \delta_2 - \delta_1 \delta_2 \right) \end{pmatrix}.
        \end{align}
